begin read only;
set local search_path=pg_catalog;
set local lock_timeout='3s';
set local statement_timeout='20s';
with inventory as (
select 'schema' k,nspname::text n,jsonb_build_array(pg_get_userbyid(nspowner),nspacl::text) v from pg_namespace where nspname='business_auth'
union all select 'function',n.nspname||'.'||p.proname||'('||pg_get_function_identity_arguments(p.oid)||')',jsonb_build_array(pg_get_functiondef(p.oid),pg_get_userbyid(p.proowner),p.proacl::text) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='business_auth' or (n.nspname,p.proname) in (('studio_workflow','context'),('public','studio_role'),('public','studio_bind_member'),('public','studio_set_device'),('public','resolve_media_delivery'),('public','triniti_admin_provision'),('public','business_session_allowed'),('public','business_auth_request_guard'),('public','triniti_business_signin_check'),('public','triniti_business_owner_access'),('public','triniti_business_finish_signin'),('public','triniti_business_cancel_signin'))
union all select 'relation',c.relname,jsonb_build_array(c.relkind,c.relrowsecurity,c.relforcerowsecurity,pg_get_userbyid(c.relowner),c.relacl::text) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='business_auth' and c.relkind in('r','p','v','m','f','S')
union all select 'column',c.relname||'.'||a.attnum::text,jsonb_build_array(a.attname,format_type(a.atttypid,a.atttypmod),a.attnotnull,a.attidentity,a.attgenerated,pg_get_expr(d.adbin,d.adrelid)) from pg_attribute a join pg_class c on c.oid=a.attrelid join pg_namespace n on n.oid=c.relnamespace left join pg_attrdef d on d.adrelid=c.oid and d.adnum=a.attnum where n.nspname='business_auth' and c.relkind in('r','p') and a.attnum>0 and not a.attisdropped
union all select 'constraint',c.relname||'.'||t.conname,to_jsonb(pg_get_constraintdef(t.oid)) from pg_constraint t join pg_class c on c.oid=t.conrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='business_auth' and t.contype<>'n'
union all select 'index',c.relname,to_jsonb(pg_get_indexdef(c.oid)) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='business_auth' and c.relkind in('i','I')
union all select 'trigger',t.tgrelid::regclass::text||'.'||t.tgname,jsonb_build_array(pg_get_triggerdef(t.oid),t.tgenabled) from pg_trigger t where not t.tgisinternal and t.tgname like 'business_auth_%'
union all select 'policy',p.polrelid::regclass::text||'.'||p.polname,jsonb_build_array(p.polpermissive,p.polcmd,(select jsonb_agg(r.rolname order by r.rolname) from pg_roles r where r.oid=any(p.polroles)),pg_get_expr(p.polqual,p.polrelid),pg_get_expr(p.polwithcheck,p.polrelid)) from pg_policy p where p.polname='business_session_required' or p.polrelid in(select oid from pg_class where relnamespace=to_regnamespace('business_auth'))
union all select 'hook',coalesce(r.rolname,'ALL')||':'||coalesce(d.datname,'ALL'),to_jsonb(c) from pg_db_role_setting s left join pg_roles r on r.oid=s.setrole left join pg_database d on d.oid=s.setdatabase cross join lateral unnest(s.setconfig) c where c like 'pgrst.db_pre_request=%' and c<>'pgrst.db_pre_request='
)
select jsonb_build_object(
 'observedAt',clock_timestamp(),'executor',current_user,'readOnly',current_setting('transaction_read_only')='on',
 'marker',obj_description(to_regnamespace('business_auth'),'pg_namespace'),
 'fingerprint',(select md5(coalesce(jsonb_agg(jsonb_build_array(k,n,v) order by k,n)::text,'[]')) from inventory),
 'catalog',(select jsonb_agg(jsonb_build_object('k',k,'n',n,'v',v) order by k,n) from inventory),
 'eligiblePolicyTables',(select coalesce(jsonb_agg(c.oid::regclass::text order by c.oid::regclass::text),'[]'::jsonb) from pg_class c join pg_namespace n on n.oid=c.relnamespace where c.relkind='r' and c.relrowsecurity and (n.nspname in('public','creator_finance','marketplace_ops','storage') or(n.nspname='realtime' and c.relname='messages')) and not(n.nspname='storage' and c.relname in('migrations','buckets_vectors','vector_indexes'))),
 'excludedProviderMetadata',(select jsonb_agg(jsonb_build_object('name',c.relname,'owner',pg_get_userbyid(c.relowner),'rls',c.relrowsecurity,'acl',c.relacl::text,'columns',(select jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'notNull',a.attnotnull)order by a.attnum)from pg_attribute a where a.attrelid=c.oid and a.attnum>0 and not a.attisdropped))order by c.relname)from pg_class c where c.relnamespace='storage'::regnamespace and c.relkind='r' and c.relname in('migrations','buckets_vectors','vector_indexes')),
 'excludedProviderMetadataPolicyCount',(select count(*) from pg_policy p join pg_class c on c.oid=p.polrelid where c.relnamespace='storage'::regnamespace and c.relname in('migrations','buckets_vectors','vector_indexes')),
 'policyAuthorityMissing',(select count(*) from pg_class c join pg_namespace n on n.oid=c.relnamespace where c.relkind='r' and c.relrowsecurity and (n.nspname in('public','creator_finance','marketplace_ops','storage') or(n.nspname='realtime' and c.relname='messages')) and not(n.nspname='storage' and c.relname in('migrations','buckets_vectors','vector_indexes')) and pg_get_userbyid(c.relowner)<>current_user and not coalesce(((coalesce(nullif(current_setting('supautils.policy_grants',true),''),'{}')::jsonb)->current_user::text)?(n.nspname||'.'||c.relname),false)),
 'privateTableAccess',(select count(*) from pg_class c cross join (values('anon'),('authenticated'),('service_role')) r(role) where c.relnamespace=to_regnamespace('business_auth') and c.relkind='r' and has_table_privilege(r.role,c.oid,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER')),
 'privateFunctionAccess',(select count(*) from pg_proc p cross join (values('anon'),('authenticated'),('service_role')) r(role) where p.pronamespace=to_regnamespace('business_auth') and has_function_privilege(r.role,p.oid,'EXECUTE')),
 'privateSchemaAccess',(select count(*) from (values('anon'),('authenticated'),('service_role')) r(role) where has_schema_privilege(r.role,'business_auth','USAGE')),
 'businessAuthSessions',(select count(*) from auth.sessions s join public.profiles p on p.id=s.user_id where p.account_type='business'),
 'accountSeedCount',(select count(*) from business_auth.accounts),
 'businessProfileCount',(select count(*) from public.profiles where account_type='business'),
 'accountSeedMatchesCurrentBusinessProfiles',not exists((select business_id from business_auth.accounts except select id from public.profiles where account_type='business') union all (select id from public.profiles where account_type='business' except select business_id from business_auth.accounts)),
 'otherPrivateRows',(select count(*) from business_auth.attempts)+(select count(*) from business_auth.device_keys)+(select count(*) from business_auth.events)+(select count(*) from business_auth.grants)+(select count(*) from business_auth.owner_seats)+(select count(*) from business_auth.sessions),
 'journal',(select coalesce(jsonb_agg(jsonb_build_object('version',version,'name',name,'statementCount',cardinality(statements),'queryBytes',octet_length(array_to_string(statements,E'\n')),'querySha256',encode(sha256(convert_to(array_to_string(statements,E'\n'),'UTF8')),'hex')) order by version),'[]'::jsonb) from supabase_migrations.schema_migrations where name like 'qa_business_auth_08_%'),
 'scope','Hosted activation observation. Compare every static catalog row to the source fixture and every business policy to the complete current eligible-table enumeration; do not substitute the fixture policy count.'
) as postflight;
rollback;
